-- i18n.lua — UI language state, multi-language dictionaries, engine
-- language detection. Languages: zh (source), en, zht (Traditional Chinese,
-- dictionary generated by tools/gen_i18n_zht.py into i18n_zht.lua).
--
-- Contract (phase 1, 2026-07-23):
-- * Chinese source strings ARE the translation keys (gettext style). A key
--   missing from the dictionary falls back to the Chinese original — the UI
--   can never crash or blank out because of an untranslated string.
-- * string.format templates keep their %-placeholders; the zh and en
--   templates must use the SAME placeholder sequence (enforced by
--   tools/test_v13.py). When English needs a different argument ORDER,
--   use tf() with named {key} placeholders instead.
-- * M.lang is the EFFECTIVE language ("zh"/"en"/"zht"), resolved by
--   ui.lua from the language=auto|zh|en|zht config via resolve(). Default zh.
local M = {}

M.lang = "zh"

-- Engine language detection. KismetInternationalizationLibrary is the
-- standard UE surface (same StaticFindObject pattern the mod already uses
-- for WidgetBlueprintLibrary). FString marshalling has had issues in
-- UE4SS experimental builds (RE-UE4SS #938 family), so every call sits in
-- its own pcall and any failure just falls through — worst case: Chinese.
function M.normalize(code)
    if type(code) ~= "string" or code == "" then return nil end
    local c = code:lower():gsub("_", "-")
    if c:find("^zh") then
        -- Traditional-script cultures: zh-Hant plus the regional tags that
        -- imply it (TW/HK/MO). Everything else Chinese is Simplified.
        if c:find("hant") or c:find("^zh%-tw") or c:find("^zh%-hk")
            or c:find("^zh%-mo") then
            return "zht"
        end
        return "zh"
    end
    return "en"   -- every non-Chinese culture falls back to English
end

-- Accept a marshalled return value ONLY if it looks like a culture code
-- (codex i18n-p1 #4: a table/userdata identity string like "table: 0x…"
-- would otherwise normalize to "en" AND swallow the culture fallback).
-- Field trace 2026-07-24: UE4SS marshals the FString RETURN as userdata
-- whose tostring() is "FString: 0x…" (type + address, not the content) —
-- the content needs :ToString(), same idiom as GetText():ToString().
local function culture_str(v)
    if v == nil then return nil end
    local s
    if type(v) == "string" then
        s = v
    else
        pcall(function() s = v:ToString() end)
        if type(s) ~= "string" then s = tostring(v) end
    end
    if type(s) ~= "string" or s == "" or #s > 20 then return nil end
    if not s:match("^%a[%w%-_]*$") then return nil end
    return s
end

-- Every probe step is recorded into M.last_detect_report so a field machine
-- can tell WHERE detection died (lib missing / call error / value rejected)
-- from one trace line — added after a 2026-07-24 field report where auto
-- never switched despite manual en working fine.
function M.detect()
    local report = {}
    local lib
    pcall(function()
        lib = StaticFindObject(
            "/Script/Engine.Default__KismetInternationalizationLibrary")
    end)
    if not lib then
        M.last_detect_report = "lib=nil"
        return nil
    end
    local function probe(name, call)
        local raw, ok
        ok = pcall(function() raw = call() end)
        local s = culture_str(raw)
        report[#report + 1] = name .. "="
            .. (not ok and "err"
                or (s or ("rej:" .. tostring(raw):sub(1, 24))))
        return s
    end
    local got = probe("lang", function() return lib:GetCurrentLanguage() end)
    if not got then
        got = probe("culture", function() return lib:GetCurrentCulture() end)
    end
    if not got then
        got = probe("locale", function() return lib:GetCurrentLocale() end)
    end
    local norm = M.normalize(got)
    report[#report + 1] = "norm=" .. tostring(norm)
    M.last_detect_report = table.concat(report, " ")
    return norm
end
M._culture_str = culture_str   -- pinned by tools/test_v13.py

-- pref: "auto" | "zh" | "en" | "zht"  ->  effective language
function M.resolve(pref)
    if pref == "zh" or pref == "en" or pref == "zht" then return pref end
    return M.detect() or "zh"
end

function M.t(zh)
    if M.lang ~= "zh" then
        local d = M.dicts and M.dicts[M.lang]
        local e = d and d[zh]
        if e then return e end
    end
    return zh
end

-- named-placeholder template: tf("已锁定 {n} 只：{names}", {n=2, names=".."})
-- Use ONLY when the English wording needs a different argument order than
-- the Chinese; otherwise keep string.format with an identical %-sequence.
function M.tf(zh, params)
    local s = M.t(zh)
    return (s:gsub("{([%w_]+)}", function(k)
        local v = params and params[k]
        if v ~= nil then return tostring(v) end
        return "{" .. k .. "}"
    end))
end

